      "title": "Florence-X Collaborative Reasoning Interface",
      "section": "Architecture",
      "summary": "Florence-X Collaborative Reasoning Interface UX Design for Team-Based Collaborative Reasoning This document specifies the user experience design for the Florence-X Collaborative Reasoning Interface — the executable layer that puts the Team Reasoning System 22-team-reasoning-system.md and Team Reasoning Protocol 23-team-reasoning-protocol.md into practice.",
      "excerpt": "Florence-X Collaborative Reasoning Interface UX Design for Team-Based Collaborative Reasoning This document specifies the user experience design for the Florence-X Collaborative Reasoning Interface — the executable layer that puts the Team Reasoning System 22-team-reasoning-system.md and Team Reasoning Protocol 23-team-reasoning-protocol.md into practice. The interface is designed to guide clinical thinking rather than merely display information. --- Core Design Principle The interface should guide thinking — not just display information. Every panel, interaction, and visual element serves the purpose of structuring and supporting the team's reasoning process under pressure. --- Primary Screen: \"Reasoning Command Center\" The main interface is organized around a single screen divided into six functional panels: 1. Problem Panel Top Center Displays the active problem definition including: Element Description --------- ------------- Problem Statement Clear, concise articulation of the clinical issue Constraints Boundary conditions time, resources, patient status Desired Outcome The target state the team is working toward --- 2. Decomposition Panel Left Presents a tree structure that breaks the problem into subproblems: The decomposition follows the structural analysis phase of the Team Reasoning Protocol 23-team-reasoning-protocol.md , ensuring problems are atomized into independently addressable components before reasoning begins. --- 3. Pathway Panel Center Each potential solution path is displayed as a card containing: Field Description ------- ------------- Path Label Iden",
