      "id": "27-tacit-knowledge-system-md",
      "file": "27-tacit-knowledge-system.md",
      "path": "27-tacit-knowledge-system.md",
      "title": "Tacit Knowledge Capture System",
      "section": "Architecture",
      "summary": "Tacit Knowledge Capture System Turning Frontline Intuition into System Intelligence This document describes the 5-layer Tacit Knowledge Capture System for Florence-X, NIN, and NAIO. It defines the design philosophy, architecture, practical implementation, and failure modes for converting frontline clinical intuition into reusable institutional intelligence.",
      "excerpt": "Tacit Knowledge Capture System Turning Frontline Intuition into System Intelligence This document describes the 5-layer Tacit Knowledge Capture System for Florence-X, NIN, and NAIO. It defines the design philosophy, architecture, practical implementation, and failure modes for converting frontline clinical intuition into reusable institutional intelligence. This system sits alongside the Gold Moment SOP 29-gold-moment-sop.md operational workflow, the Gold Moment Capture UI 28-gold-moment-capture-ui.md interface specification, the AI Signal Schema 30-ai-signal-schema.md data model, and the Intuition-to-Intelligence Module 31-intuition-to-intelligence-module.md learning engine. --- Design Objective The interface must help a frontline clinician accomplish four things in under one minute: 1. Notice something meaningful 2. Name what triggered concern or action 3. Classify the situation enough for downstream use 4. Share it without writing a full narrative The UI should not feel like charting. It should feel like capturing a signal . That matters because the highest-value knowledge is usually: pre-verbal, pattern-based, situational, and socially testable only after the fact. --- Core Interface Principle Signal first, structure second, narrative last. The clinician should never begin with a blank text box. --- What This System Does Traditional System Your System --- --- Knowledge → written → stored Knowledge emerges through reasoning → captured → validated → embedded into workflows --- The 5-Layer Tacit Knowledge System Layer 1: Trigger — \"Moments That Matter\" You do not capture e",
