      "file": "28-gold-moment-capture-ui.md",
      "path": "28-gold-moment-capture-ui.md",
      "title": "Florence-X Gold Moment Capture UI",
      "section": "Architecture",
      "summary": "Florence-X Gold Moment Capture UI Interface specification for the Gold Moment Capture screen — the primary clinician-facing input mechanism of the Florence-X Tacit Knowledge System. Designed for sub-30-second signal capture with minimal cognitive load, mobile-first. Part of the broader Tacit Knowledge System 27-tacit-knowledge-system.md .",
      "excerpt": "Florence-X Gold Moment Capture UI Interface specification for the Gold Moment Capture screen — the primary clinician-facing input mechanism of the Florence-X Tacit Knowledge System. Designed for sub-30-second signal capture with minimal cognitive load, mobile-first. Part of the broader Tacit Knowledge System 27-tacit-knowledge-system.md . See also the operational procedures in Gold Moment SOP 29-gold-moment-sop.md and the data structure in AI Signal Schema 30-ai-signal-schema.md . --- Design Principle Capture signals, not stories. The interface is intentionally lightweight. If it feels like charting, it will fail. If it feels like capturing a thought, it will scale. --- Primary Screen: Gold Moment Capture Header \"What just mattered?\" Subtext: Capture the moment before it disappears. --- Input Flow The capture flow follows a five-step sequence optimized for speed and low cognitive overhead. 1. Trigger Type Quick-select buttons no typing required : Trigger Description --------- ------------- Early concern A developing issue spotted before it escalates Near miss An event that almost caused harm or failure Workaround A deviation from standard process to get the job done Escalation A situation requiring higher-level intervention Handoff gap Information or responsibility lost during transfer Workflow friction Repeated friction or inefficiency in a process 2. Observation Prompt \"What did you notice?\" Free-text field optimized for short, natural-language input. No structured fields or mandatory long-form text. 3. Action Trigger \"What made you act?\" Captures the specific cue or cont",
