      "id": "29-gold-moment-sop-md",
      "file": "29-gold-moment-sop.md",
      "path": "29-gold-moment-sop.md",
      "title": "Gold Moment Review SOP",
      "section": "Architecture",
      "summary": "Gold Moment Review SOP Unit-Level Protocol for Converting Frontline Intuition into System Intelligence --- Purpose To identify, review, validate, and operationalize high-value frontline insights that emerge during routine care, escalation, near misses, workarounds, and coordination events. Definition A Gold Moment is a brief frontline event in which a clinician, staff member, or team recognized something important before it was formally obvious, prevented harm, improved flow, or exposed a hidden system weakness.",
      "excerpt": "Gold Moment Review SOP Unit-Level Protocol for Converting Frontline Intuition into System Intelligence --- Purpose To identify, review, validate, and operationalize high-value frontline insights that emerge during routine care, escalation, near misses, workarounds, and coordination events. Definition A Gold Moment is a brief frontline event in which a clinician, staff member, or team recognized something important before it was formally obvious, prevented harm, improved flow, or exposed a hidden system weakness. Gold Moments are captured in real time via the Gold Moment Capture UI 28-gold-moment-capture-ui.md and are rooted in the broader Tacit Knowledge System 27-tacit-knowledge-system.md . The review process is the bridge that converts these raw signals into institutional learning as described in the Intuition-to-Intelligence Module 31-intuition-to-intelligence-module.md . --- Criteria A moment qualifies if it includes one or more of: - Early recognition before conventional metrics - Useful deviation from routine process - Prevention of error or delay - Tacit coordination move that changed outcome - Workaround revealing a system flaw - Patient/family interaction that materially changed care - Subtle handoff or communication insight - Insight with repeat relevance --- Roles Role Responsibilities ------ ----------------- Unit Facilitator Usually charge nurse, educator, CNS, or UBC lead. Responsible for running the review. Signal Steward Reviews submitted moments before the meeting and prepares the queue. Frontline Contributors Present or clarify the original signal if neede",
