      "summary": "The Lane Operator Handbook Day-to-Day Operations for the Seven Lanes of the Full Stack Program File Reference: 34-lane-operator-handbook.md Scope: The working manual for Lane Operators — the nurses or, in two cases, nurse-engineer pairs who run citizenship onboarding, contribution intake, peer review, and mentor pool management for a single lane of the Full Stack Program.",
      "excerpt": "The Lane Operator Handbook Day-to-Day Operations for the Seven Lanes of the Full Stack Program File Reference: 34-lane-operator-handbook.md Scope: The working manual for Lane Operators — the nurses or, in two cases, nurse-engineer pairs who run citizenship onboarding, contribution intake, peer review, and mentor pool management for a single lane of the Full Stack Program. Covers universal responsibilities, weekly and quarterly cadence, KPIs, and cross-lane coordination, then provides lane-specific operating notes for each of the seven lanes. Related Documents: - The Full Stack Program 32-full-stack-program.md — strategic foundation - The Stack Passport Entry Kit 33-stack-passport-entry-kit.md — intake and onboarding tooling - Florence-X + NIN Full Stack Architecture 10-florence-architecture.md — the eight-layer stack each lane maps to - Competency Framework 35-reviewer-bench-curriculum.md — the skill tiers Lane Operators must possess - Cultural Playbook 18-cultural-playbook.md — the voice and rituals Lane Operators enforce --- I. How to Use This Handbook The handbook has two halves. The first half covers what every Lane Operator does — role, cadence, duties, KPIs, failure modes. The second half covers what each of the seven Lane Operators does differently . Read the first half once. Return to your lane's second-half section when you need it. If you are… Go to ------------- ------- A new Lane Operator in your first 30 days §II–§VIII in order, then your lane's section An experienced Operator triaging a problem §VII Failure Modes , §VI Coordination , your lane's section A Prog",
