      "title": "Florence-X: Personal Edition",
      "section": "Architecture",
      "summary": "Florence-X: Personal Edition Teaching Video Script — How To Build Your Personal Stack, Layer by Layer Series: NIN Foundation Seminars · Personal Practice Track Module Position: Foundation Tier, follows the Openclaw–Hermes Personal Setup seminar Runtime: ~28 minutes Format: Studio seminar with workspace demo intercuts Audience: Nurses entering the NIN install base; Stack Passport Visitor and Resident tiers Scope boundary: Personal-life practice only.",
      "excerpt": "Florence-X: Personal Edition Teaching Video Script — How To Build Your Personal Stack, Layer by Layer Series: NIN Foundation Seminars · Personal Practice Track Module Position: Foundation Tier, follows the Openclaw–Hermes Personal Setup seminar Runtime: ~28 minutes Format: Studio seminar with workspace demo intercuts Audience: Nurses entering the NIN install base; Stack Passport Visitor and Resident tiers Scope boundary: Personal-life practice only. No PHI. No clinical data. No workflow that touches a patient. Clinical orchestration is a separate, governed curriculum. Director's note on voice. Calm, grounded, unhurried. Clinical precision plus human warmth. Never hype. The presenter is a senior nurse who has already built this for themselves, not a tech influencer. Reason out loud. Pause for the viewer. End every segment on a concrete next step. --- COLD OPEN — 0:00 to 1:30 VISUAL: Presenter at a clean desk. One laptop. A printed eight-layer architecture card. Lower-third title: \"NIN Foundation Seminar · Florence-X: Personal Edition.\" PRESENTER: Before we open a single file today, I want to be precise about what this seminar is. This is not a clinical training. Nothing in the next twenty-eight minutes should ever touch a patient record, a medication order, a shift handoff, or anything protected under HIPAA. If that is what you came for, the Level 2 Clinical Orchestration track exists, it is governed, and it is the right place for that work. What this is: a supervised walk-through of how to build the personal version of Florence-X — the same eight-layer architecture you will",
