      "title": "Canonical Glossary",
      "section": "Foundation",
      "summary": "Canonical Glossary Status: Canonical Civilization Layer . Foundational reference; numbered Series C. Owners: NAIO Office IV Operational Gating ; FMN Narrative Lead; Headless Canon Liaison; Canonical Glossary Steward rotating ; Cultural Adaptation Lead. Companion docs: 04-naio-constitutional-charter.md ; Headless-Canon-Strategy.md ; IP-and-Open-Source-Doctrine.md ; Brand-and-Trademark-Defense-Doctrine.md ; Country-Implementation-Profile-Template.md .",
      "excerpt": "Canonical Glossary Status: Canonical Civilization Layer . Foundational reference; numbered Series C. Owners: NAIO Office IV Operational Gating ; FMN Narrative Lead; Headless Canon Liaison; Canonical Glossary Steward rotating ; Cultural Adaptation Lead. Companion docs: 04-naio-constitutional-charter.md ; Headless-Canon-Strategy.md ; IP-and-Open-Source-Doctrine.md ; Brand-and-Trademark-Defense-Doctrine.md ; Country-Implementation-Profile-Template.md . Voice: Calm. Definitional. Disambiguating. Vendor-neutral. Refusal-aware. --- 1. Why This Glossary Exists The canon's vocabulary is load-bearing. Charter terms joint clinical authority, Stack Passport, Stop-the-Line carry constitutional weight. Doctrinal terms Programmability Audit, Bias and Equity Ratio, Human Door carry operational weight. Refusal-rule IDs R-1, V-3, PF-7, IS-9, etc. carry contractual weight in the headless surface. When terms drift, doctrine drifts. When doctrine drifts, the canon's commitments to patients, clinicians, partners, and regulators drift with it. This glossary is the canonical reference for every term the canon uses with specific meaning. It is published in human-readable form this document and in machine-readable form an accompanying JSON-LD definitions block so AI agents and humans can both anchor on the same definitions. The glossary is one of the most-leverage headless assets the canon publishes: agents that need to summarize the canon will reach for a glossary first.",
