      "id": "00-refactor-decisions-log-md",
      "file": "00-refactor-decisions-log.md",
      "path": "00-refactor-decisions-log.md",
      "title": "Refactor Decisions Log",
      "section": "Foundation",
      "summary": "Refactor Decisions Log The structural decisions that shaped the v2/v3 canon batch, with rationale and downstream consequences. File reference: 00-refactor-decisions-log.md Status: Canonical. Decisions in this log are binding on subsequent files unless explicitly overturned. Scope: Records the load-bearing structural decisions made during the realignment refactor — the decisions that determine what the rest of the canon must square against.",
      "excerpt": "Refactor Decisions Log The structural decisions that shaped the v2/v3 canon batch, with rationale and downstream consequences. File reference: 00-refactor-decisions-log.md Status: Canonical. Decisions in this log are binding on subsequent files unless explicitly overturned. Scope: Records the load-bearing structural decisions made during the realignment refactor — the decisions that determine what the rest of the canon must square against. Related Documents: - Realignment Executive Summary 00-civilization-layer-realignment-summary.md — the diagnosis this log responds to - Core Recommendation v2 core-recommendation-v2.md — the operational v2 instruction set - Sovereign Doctrine Integration 39-sovereign-doctrine-integration.md — doctrinal basis for Layer 8 and Directive 6 --- I. Why This Log Exists A refactor of this scope produces decisions that future readers will need to retrace. Recording each decision with its rationale prevents two failure modes: the decision being reopened on every batch by people who weren't in the room when it was made, and the decision drifting silently because nobody can find the moment it was made. This log is not a meeting minutes document. It is the canonical record of the decisions that the v2/v3 canon depends on. --- II. Decision Set Decision 1 — NIN Provisions Is the Fourth Pillar of Office II Decision. NIN Provisions The Bridge, License Defense Pool, Workflow Royalty, and the material support infrastructure is added as the fourth pillar of Office II NIN Install Base , alongside the Arc, the Fellowship, and the Stack Passport.",
      "headings": [
        "I. Why This Log Exists",
        "II. Decision Set",
        "Decision 1 — NIN Provisions Is the Fourth Pillar of Office II",
        "Decision 2 — Charter v3.0 Drafts the Five Phantom Sections",
        "Decision 3 — Series C Is Authoritative; Series A and B Are Archived",
        "Decision 4 — Voice Discipline Is Enforced via the v2 Review Rubric",
        "Decision 5 — The Three-Role Human Interface Is the Default Reading",
        "Decision 6 — Layer 8 (Energy) Is Drawn Into Every Architecture Document",
        "Decision 7 — The Five New Registries Are Provisioned in This Batch as Stub References",
        "III. Decisions Explicitly Deferred",
        "Deferred 1 — Stack Congress Operating Template",
        "Deferred 2 — Cross-Layer Retrospective Infrastructure",
        "Deferred 3 — Programmability Audit Specification",
        "Deferred 4 — Refactored README and Cross-Reference Integrity Pass"
      ],
