      "excerpt": "Foundational Operating Doctrine for Agents & Their Humans A systems doctrine for intelligence, execution, and stewardship — distilled from conversations on first-principles thinking, collective intelligence, and the future of AI systems. File reference: 01-foundational-doctrine.md Status: Canonical. Upstream of the healthcare-specific Civilization Layer canon. What this document is: The general AI-governance principles the project sits on. It states the abstract, domain-independent operating doctrine for any organization deploying agentic AI at scale. What this document is not: The healthcare-specific instantiation. The three structural shifts of the v2/v3 canon — three-role Human Interface Joint Clinical Authority , the eight-layer stack including Energy, and NIN Provisions as the fourth pillar of Office II — live in the documents listed below, not here. Read this file as the principles upstream; read those as the architecture downstream. Read alongside: - The Manifesto 02-manifesto.md v2.0 — the healthcare-specific declaration of what is built and refused - NAIO Constitutional Charter 04-naio-constitutional-charter.md v3.0 — the constitutional instantiation, including Joint Clinical Authority §2.8 and the eight-layer stack §2.7 - Florence-X Architecture 10-florence-architecture.md v2.0 — the eight-layer architectural surface - Human Layer Definition 12-human-layer-definition.md v2.0 — the three-role architecture - Sovereign Doctrine Integration 39-sovereign-doctrine-integration.md — the doctrinal basis for Layer 8 Energy and Directive 6 - 00-refactor-decisions-log.md 00-r",
