      "title": "The Nurse Intelligence Manifesto",
      "section": "Foundation",
      "summary": "The Nurse Intelligence Manifesto A publishable movement document for the NIN install base, hospital leadership, regulators, physicians, allied clinicians, and the patients we serve. Version: 2.0 — Joint Clinical Authority Edition Status: Canonical. Drop-in replacement for v1.x. Scope: The structural declaration of who we are, what we are building, and what we refuse.",
