      "section": "Foundation",
      "summary": "Florence-X + NIN Full Stack Architecture The eight-layer Civilization Stack — the architectural surface on which NAIO-certified AI deployments operate. Version: 2.0 — Eight-Layer Edition Status: Canonical. Drop-in replacement for v1.x which described seven layers . Scope: Defines the eight operational layers of the Civilization Layer, the function and posture of each, the feedback loop that binds them, and the architectural prohibitions that govern what may and may not be deployed under NAIO certification.",
