      "excerpt": "NIN Fellowship Experience Design Level 1–3 Immersive Training System This document describes the progressive three-level fellowship experience that takes nurses from AI awareness to system-level AI orchestration. Each level builds on the previous one, combining hands-on practice with real-world application and culminating in measurable outcomes for the individual and the clinical unit. Related documents: - See Certification Curriculum P1_AI_Aware_Physician_Curriculum.docx for detailed module content, assessments, and credentialing pathways - See Competency Framework 35-reviewer-bench-curriculum.md for the full skill taxonomy and proficiency levels mapped to each fellowship stage - See Install Base Growth Engine 19-install-base-growth-engine.md for how fellowship graduates drive adoption across new units and hospitals --- LEVEL 1: AI-Aware Nurse Attribute Detail ----------- -------- Goal Remove fear + build familiarity Duration 1–2 weeks Approach Hands-on only Modules - What AI actually is — Demystifying AI concepts in plain, nursing-relevant language - First workflow — Building and running a first end-to-end AI-assisted workflow - Risk awareness basic EDENA — Introduction to the EDENA framework for identifying and flagging AI risks at a foundational level see full EDENA protocol in the curriculum Output - 3 working workflows the nurse can immediately use on the floor - AI literacy baseline established, with measurable pre/post assessment --- LEVEL 2: AI Operator Attribute Detail ----------- -------- Goal Build capability Duration 4–6 weeks Approach Real-world tasks Modules ",
