      "summary": "Stack Passport Entry Kit The pre-Fellowship entry kit for nurses and equivalent allied-clinician entry pathways joining the Civilization Layer through the Arc. Version: 2.0 — Provisions Integration Edition Status: Canonical. Drop-in replacement for v1.x. Audience: Nurses, physicians entering through P-1 , and allied clinicians considering Stack Citizenship; Arc facilitators; and institutional onboarding teams.",
