      "summary": "The Florence Standard A Seminar for Nursing Students on Building a $1 Billion Impactful Community File Reference: 42-florence-standard-seminar.md Module Position: Pre-Arc orientation. Suitable for second- or third-year nursing students, Doctor of Nursing Practice cohorts, and recent graduates entering the install base.",
      "excerpt": "The Florence Standard A Seminar for Nursing Students on Building a $1 Billion Impactful Community File Reference: 42-florence-standard-seminar.md Module Position: Pre-Arc orientation. Suitable for second- or third-year nursing students, Doctor of Nursing Practice cohorts, and recent graduates entering the install base. Can be delivered as a 75-minute seminar, a half-day workshop, or a recorded teaching session. Audience: Nursing students at any level. No prior NIN, NAIO, or AI experience assumed. Scope boundary: This is a formation seminar, not a clinical training and not a startup pitch class. The objective is to teach nursing students how a nursing career compounds — over decades, not quarters — into community-scale impact. Director's note on voice. Calm, grounded, unhurried. Clinical precision plus human warmth. The presenter is a senior nurse who has watched a career compound, not a tech motivator. Reason out loud. Pause for the room. End every segment with a concrete next action a learner can take this week. Related Documents: - The Arc Initiation Program 37-arc-initiation-program.md — the 21-day pre-Fellowship program this seminar feeds into - The Full Stack Program 32-full-stack-program.md — the participation architecture the seminar references - Stack Passport Entry Kit 33-stack-passport-entry-kit.md — the credential the seminar concludes by inviting the learner toward - The Nurse Intelligence Manifesto 02-manifesto.md — the doctrinal frame for the role of the nurse - Florence-X Personal Edition Teaching Script Florence-X-Personal-Edition-Teaching-Script.md — the fo",
