      "title": "Stack Congress Operating Template",
      "section": "Foundation",
      "summary": "Stack Congress Operating Template The annual two-day governance ritual at which the install base convenes to decide what becomes canonical, what gets retired, what is recognized, and what direction the canon takes next. Operating template: agenda, participant rights and voting weights, proposal lifecycle, canonization protocol, recognition process, public progress report format, and between-Congress decision authority.",
      "excerpt": "Stack Congress Operating Template The annual two-day governance ritual at which the install base convenes to decide what becomes canonical, what gets retired, what is recognized, and what direction the canon takes next. Operating template: agenda, participant rights and voting weights, proposal lifecycle, canonization protocol, recognition process, public progress report format, and between-Congress decision authority. File reference: 51-stack-congress-operating-template.md Version: 1.0 — Joint Clinical Authority Edition Status: Canonical. Inaugural operating template under core-recommendation-v2.md core-recommendation-v2.md §11 and §A.6, and named in Refactor Decisions Log §III Deferred 1 . Audience: Stack Congress Convenor NAIO Office I , Stewards and Keepers from across the install base, Office I/II/III/IV/V/VI/VII/VIII designates, P-4 Council members, AS/AT/AR/AL/AD/AP-3 credential holders, institutional executives, labor counterparties as observers, regulator and patient-voice observers. Scope: Full operating template for the annual Stack Congress. Covers: convocation logistics, two-day agenda structure, participant rights and voting weights, proposal lifecycle and canonization protocol, retirement protocol, top-country/top-organization/top-pilot recognition, public progress report format, and the between-Congress decision authority that operates between annual sessions. The Stack Congress is the single most important governance ritual the canon runs; this template is what makes it operate canonically rather than ceremonially. Related Documents: - Core Recommendation v",
