      "file": "53-layer-8-energy-doctrine.md",
      "path": "53-layer-8-energy-doctrine.md",
      "title": "Layer 8 — Energy Doctrine",
      "section": "Foundation",
      "summary": "Layer 8 — Energy Doctrine Status: Canonical Civilization Layer . Numbered Series C foundational architecture doctrine. Operationalizes Layer 8 of the eight-layer stack. Owners: NAIO Office VI Continuity ; Florence-X Engineering Lead; Energy Citizen leadership; Sustainability Lead; Cultural Adaptation Lead. Companion docs: 04-naio-constitutional-charter.md §3.4 Stack Transparency ; 10-florence-architecture.md ; 11-edge-system-solutions.md ; 32-full-stack-program.md ; 39-sovereign-doctrine-integration.md ; 48-continu",
      "excerpt": "Layer 8 — Energy Doctrine Status: Canonical Civilization Layer . Numbered Series C foundational architecture doctrine. Operationalizes Layer 8 of the eight-layer stack. Owners: NAIO Office VI Continuity ; Florence-X Engineering Lead; Energy Citizen leadership; Sustainability Lead; Cultural Adaptation Lead. Companion docs: 04-naio-constitutional-charter.md §3.4 Stack Transparency ; 10-florence-architecture.md ; 11-edge-system-solutions.md ; 32-full-stack-program.md ; 39-sovereign-doctrine-integration.md ; 48-continuity-attestation-registry-spec.md ; Compute-Sovereignty-and-Hardware-Doctrine.md ; Country-Implementation-Profile-Template.md . Voice: Calm. Operational. Sustainability-positive without greenwashing. Continuity-anchored. Refusal-positive. --- 1. Why This Doctrine Exists The canon's eight-layer stack names Layer 8 Energy as foundational, equal in canonical weight to Compute Layer 7 , Tools and Data Layer 6 , Agents Layer 5 , Florence-X Orchestration Layer 4 , EDENA Layer 3 , NAIO Layer 2 , and NIN Layer 1 . The Full Stack Program designates Lane 8 with an Energy Citizen role. The Continuity Attestation Registry requires an Energy Citizen signatory for Yellow/Red zone workflows. What the canon has lacked is a doctrine specifying the substantive content of Layer 8 — what energy posture means in canonical practice. Until this doctrine, Layer 8 has been named but thinly specified: a placeholder for a commitment that needed canonical substance. This doctrine specifies that substance: the canon's posture on energy supply renewable preference; no greenwashing; demand-respo",
