      "id": "ai-agent-rights-and-non-rights-posture-md",
      "file": "AI-Agent-Rights-and-Non-Rights-Posture.md",
      "path": "AI-Agent-Rights-and-Non-Rights-Posture.md",
      "title": "AI Agent Rights and Non-Rights Posture",
      "section": "Foundation",
      "summary": "AI Agent Rights and Non-Rights Posture Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; NAIO Office IV Operational Gating ; FMN Narrative Lead; Patient and Family Voice Council Liaison; General Counsel. Companion docs: 04-naio-constitutional-charter.md §2.8 Joint Clinical Authority; §2.9 Patient Dignity ; AI-Agent-Lifecycle-Doctrine.md ; Patient-Facing-AI-Doctrine.md ; Vulnerable-Populations-Doctrine.md ; Insurance-Liability-Indemnity-Doctrine.md ; IP-and-Open-Source-Doctrine.md ; Headless-C",
      "excerpt": "AI Agent Rights and Non-Rights Posture Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; NAIO Office IV Operational Gating ; FMN Narrative Lead; Patient and Family Voice Council Liaison; General Counsel. Companion docs: 04-naio-constitutional-charter.md §2.8 Joint Clinical Authority; §2.9 Patient Dignity ; AI-Agent-Lifecycle-Doctrine.md ; Patient-Facing-AI-Doctrine.md ; Vulnerable-Populations-Doctrine.md ; Insurance-Liability-Indemnity-Doctrine.md ; IP-and-Open-Source-Doctrine.md ; Headless-Canon-Strategy.md ; Foundational_Doctrine_for_Human_Governance_of_AI_Agents.md . Voice: Calm. Philosophically clear. Refusal-positive. Anti-anthropomorphic. Patient-protective. Anti-rhetorical-drift. Counsel note: This doctrine is canonical posture, not legal advice. Specific jurisdictions may develop distinct legal positions on AI personhood; counsel implements jurisdictionally. --- 1. Why This Doctrine Exists As AI agents accrue persistent memory, apparent identity, conversational continuity, and increasing autonomy in narrow tasks, the field will be asked — repeatedly, in venues from product marketing to legislative hearings to courtrooms — whether AI agents have rights . Whether they have moral standing. Whether their \"termination\" is a kind of harm. Whether they can hold IP, sign contracts, be parties to lawsuits, hold professional credentials, exercise refusals on their own behalf, or be liable in their own name. The canon will be asked. Patients will be asked. Clinicians will be asked. Vendors will press the question, sometimes for marketing advantage, somet",
