      "excerpt": "\"What if we could scale good?\" Campaign Kit Full operational kit for FMN's flagship campaign. Manifesto, landing page, video scripts, 30-day social campaign, posts and carousels, newsletter sequence, story prompts, challenges, executive briefing, classroom guide, partner outreach, measurement dashboard, risk checklist. File reference: FMN-Scale-Good-Campaign-Kit.md Version: 1.0 — Launch Status: Canonical campaign kit . Companion to FMN-Doctrine-and-Operating-Blueprint.md FMN-Doctrine-and-Operating-Blueprint.md §17–§19 and FMN-Founder-Launch-Essay.md FMN-Founder-Launch-Essay.md . Audience: FMN editorial team, campaign producers, content creators, partner organizations, contributing voices. Compliance note. Campaign claims, patient stories, institutional naming, and labor language should be reviewed per the Editorial Governance Manual. The institution's compliance and legal teams must validate jurisdiction-specific requirements. --- 1. Campaign Manifesto Title What if we could scale good? Manifesto Text There is a moment in healthcare we are all living through, whether we have named it or not. Intelligence is scaling. Artificial intelligence — the kind that drafts notes, recommends actions, summarizes records, predicts outcomes, automates routine — is being deployed in healthcare faster than most institutions can govern it. It is being adopted as fragmented tools, vendor pilots, point solutions. Each adoption decision is local.",
