      "excerpt": "Florence Media Network — Website Copy Full website copy across 14 pages with SEO meta. Companion to the Doctrine and Operating Blueprint. File reference: FMN-Website-Copy.md Version: 1.0 — Launch Status: Canonical website copy . Companion to FMN-Doctrine-and-Operating-Blueprint.md FMN-Doctrine-and-Operating-Blueprint.md §16. Audience: Web team, content management; FMN editorial team for periodic refresh. Compliance note. Each page should be reviewed by Privacy Editor for PHI considerations and Legal Liaison for any regulatory language. Institutional brand standards apply. --- Homepage SEO Title Florence Media Network — Belief-Shaping Media Layer for Human-Led AI in Healthcare Meta Description Florence Media Network translates nurse-led AI governance into stories, campaigns, and public understanding. Subscribe for stories, signals, and refusals from healthcare's human control layer. Hero Section Headline: What if we could scale good? Subheadline: Intelligence is scaling. We must scale care, dignity, safety, and trust to match. CTAs: - Subscribe to FMN - Read the Manifesto - Apply to NIN \"The Moment\" Section Healthcare is in a moment most institutions have not yet named. AI is scaling faster than governance, faster than trust. Workflows, decisions, and communications are increasingly shaped by intelligence systems that are powerful, fast, and persuasive — but not yet trustworthy at the scale of patient care. The institutions that adopt AI without architecture will scale errors faster than benefits.",
