      "excerpt": "IP and Open-Source Doctrine Status: Canonical Civilization Layer . Owners: NAIO Office II NIN Install Base; Workflow Royalty ; General Counsel; FMN Narrative Lead; Florence-X Engineering Lead; EDENA Safety/Ethics Lead. Companion docs: 04-naio-constitutional-charter.md §3.4 Stack Transparency; §4.5 Spec Author of record ; 43-nin-provisions.md Workflow Royalty; License Defense Pool ; 46-spec-author-registry-spec.md ; Headless-Canon-Strategy.md license metadata ; Vendor-Risk-Management-Doctrine.md vendor IP and model selection ; Training-Data-and-Derivative-Data-Doctrine.md ; Brand-and-Trademark-Defense-Doctrine.md ; 00-canonical-glossary.md ; Insurance-Liability-Indemnity-Doctrine.md . Voice: Calm. Counsel-aware this doctrine sets canonical posture, not legal advice . Open-default. Vendor-neutral. Refusal-positive. Author-respectful. Counsel note: This doctrine is canonical posture, not legal advice. Specific licenses, filings, and IP matters require qualified counsel. The doctrine establishes the canon's stance; counsel implements it. --- 1. Why This Doctrine Exists The canon has, to this point, written license metadata into individual documents CC-BY-4.0 in YAML frontmatter and JSON-LD , referenced Workflow Royalty in NIN Provisions, established Spec Author of record in Charter §4.5, and noted IP exposure in the Vendor Risk Management Doctrine. No canon-wide IP and open-source doctrine has tied those threads together. The threads matter because IP posture is downstream from many other choices: who can fork the canon, who can build on Florence-X, who owns spec-authored workf",
