      "summary": "NIN Training Philosophy & Handbook The formation philosophy underneath the Civilization Layer canon — what it means to make a stack citizen, why the canon refuses to call this \"training,\" and how Lane Operators and Mentors actually do the work. File reference: NIN_Nursing_Intelligence_Training_Philosophy_Handbook.md Version: 2.0 — Joint Clinical Authority Edition Status: Canonical.",
