      "id": "openclaw-hermes-setup-video-script-md",
      "file": "Openclaw-Hermes-Setup-Video-Script.md",
      "path": "Openclaw-Hermes-Setup-Video-Script.md",
      "title": "Openclaw–Hermes Personal Setup",
      "section": "Foundation",
      "summary": "Openclaw–Hermes Personal Setup Teaching Video Script — Building the Execution and Memory Layers of Your Personal Stack Series: NIN Foundation Seminars · Personal Practice Track Module Position: Foundation Tier, precedes the Florence-X: Personal Edition seminar. This is the foundation setup; Personal Edition assumes its environment is installed.",
      "excerpt": "Openclaw–Hermes Personal Setup Teaching Video Script — Building the Execution and Memory Layers of Your Personal Stack Series: NIN Foundation Seminars · Personal Practice Track Module Position: Foundation Tier, precedes the Florence-X: Personal Edition seminar. This is the foundation setup; Personal Edition assumes its environment is installed. Runtime: ~25 minutes Format: Studio seminar with workspace setup intercuts Audience: Nurses entering the NIN install base; Stack Passport Visitor tier and pre-Resident entrants Scope boundary: Personal-life practice only. No PHI. No clinical data. No workflow that touches a patient. Clinical orchestration is a separate, governed curriculum. Director's note on voice. Calm, grounded, unhurried. Clinical precision plus human warmth. Never hype. The presenter is a senior nurse who has already built this for themselves, not a tech influencer. Reason out loud. Pause for the viewer. End every segment on a concrete next step. This script is the foundation that the Florence-X Personal Edition Teaching Script Florence-X-Personal-Edition-Teaching-Script.md builds on; voice continuity matters. Related Documents: - Florence-X Personal Edition Teaching Script Florence-X-Personal-Edition-Teaching-Script.md — the seminar this one precedes - Stack Passport Entry Kit 33-stack-passport-entry-kit.md — captures the assignment artifact at the end of this seminar - The Manifesto 02-manifesto.md — the principles this seminar lives inside - Cultural Playbook 18-cultural-playbook.md — voice and tone reference for the presenter --- COLD OPEN — 0:00 to 1:30 VIS",
