      "id": "robotics-add-on-4-robots-must-serve-care-campaign-kit-md",
      "file": "Robotics-Add-on-4-Robots-Must-Serve-Care-Campaign-Kit.md",
      "path": "Robotics-Add-on-4-Robots-Must-Serve-Care-Campaign-Kit.md",
      "title": "Robots Must Serve Care — Campaign Kit",
      "section": "Foundation",
      "summary": "Robots Must Serve Care — Campaign Kit Status: Canonical Civilization Layer . Campaign derived from Healthcare-Robotics-Governance-Doctrine.md §21. Operates through FMN under NIN LLC per Legal-Entity-Architecture-Doctrine.md with editorial discipline per FMN-Editorial-Governance-Manual.md and media relations per Media-Relations-Strategy-Playbook.md .",
      "excerpt": "Robots Must Serve Care — Campaign Kit Status: Canonical Civilization Layer . Campaign derived from Healthcare-Robotics-Governance-Doctrine.md §21. Operates through FMN under NIN LLC per Legal-Entity-Architecture-Doctrine.md with editorial discipline per FMN-Editorial-Governance-Manual.md and media relations per Media-Relations-Strategy-Playbook.md . Owners: FMN Narrative Lead; Media Relations Lead; NAIO Office VIII; Robotics Steward; Patient and Family Voice Council Liaison. Voice: Calm. Safety-first. Pro-innovation. Human-centered. Standards-driven. Not anti-robot. Not techno-utopian. Not fearmongering. Not vendor-led. Patient-centered. Workforce-respecting. --- 1. Campaign Manifesto Robots Must Serve Care. Robots can lift. They can move. They can transport. They can clean. They can extend the reach of human capability. In healthcare, those gains are real. We welcome them. But healthcare is not a warehouse. A patient is not a parcel. A clinician is not a function to be replaced. Care is the work of humans who think, judge, advocate, and stay with people through the moments that machines cannot understand. So we say it plainly: in healthcare, robots must serve care. They must not replace it. We commit to standards before scale. To safety before autonomy. To dignity before automation. To joint clinical authority — nurses orchestrate, physicians decide within scope, allied clinicians hold discipline-specific safety — across every robotic deployment.",
