      "summary": "NAIO–Florence–EDENA Edge System Solutions Unit-Level Deployment Architecture This document defines the NAIO-Florence-EDENA edge system solutions at the unit level for clinical departments, ancillary departments, outpatient, and ambulatory centers. It maps the 5-layer edge architecture 10-florence-architecture.md from Florence Architecture 10-florence-architecture.md onto specific healthcare settings and describes the deployment model, cross-unit orchestration, and system-level positioning of the multi-agent operati",
