      "section": "Governance",
      "summary": "NIN Cultural Playbook Daily rituals, behaviors, and language that define the NIN practitioner identity. This document operationalizes the canon's cultural principles into concrete, repeatable actions. Status: Canonical Civilization Layer . Promoted to canonical status in Cluster H was supplementary . Cultural foundation for NIN workforce identity; extends across Country Implementation Profile adaptations.",
      "excerpt": "NIN Cultural Playbook Daily rituals, behaviors, and language that define the NIN practitioner identity. This document operationalizes the canon's cultural principles into concrete, repeatable actions. Status: Canonical Civilization Layer . Promoted to canonical status in Cluster H was supplementary . Cultural foundation for NIN workforce identity; extends across Country Implementation Profile adaptations. Voice: Calm. Practitioner-respectful. Pragmatic. --- Citation Card Cite as: NIN Cultural Playbook, version 1.0, NIN-NAIO Civilization Layer Canon, https://canon.example/18-cultural-playbook.md, retrieved <date . --- A. Daily Rituals Non-Negotiable 1. The Morning Orientation 5 minutes Every NIN member starts the day with three questions: - What problem am I solving today? - Where can AI assist? - Where must I supervise? Outcome: Intentional use, not passive consumption. 2. The First Workflow Rule Every day: Build or refine one micro-workflow. Examples: - Shift report summarization - Patient education draft - Staffing insight dashboard Outcome: Continuous skill compounding. 3. The Reasoning Out Loud Practice Always explain reasoning, not just answers: - Share how you used AI - Show your assumptions - Invite critique Outcome: Collective intelligence. See also Team Reasoning System 22-team-reasoning-system.md for structured collaborative reasoning protocols. 4. The Human Checkpoint Before any output, ask: - Does this make sense clinically? - Would I trust this for a patient? - What could go wrong? Outcome: Embeds EDENA thinking at the behavior level. For the full framework on ",
