      "summary": "Team Reasoning System Collective Cognitive Architecture for Complex Decisions This document defines the team reasoning model — how groups reason, explore, and converge on outcomes under complexity. It describes the core principles, operational mechanics, orchestration structure, and failure modes of teams functioning as shared reasoning engines.",
      "excerpt": "Team Reasoning System Collective Cognitive Architecture for Complex Decisions This document defines the team reasoning model — how groups reason, explore, and converge on outcomes under complexity. It describes the core principles, operational mechanics, orchestration structure, and failure modes of teams functioning as shared reasoning engines. See also: - Team Reasoning Protocol 23-team-reasoning-protocol.md — step-by-step operational protocol for running team reasoning sessions - Collaborative Reasoning Interface 24-collaborative-reasoning-interface.md — the interface layer enabling hybrid human-AI reasoning - Committee Redesign 25-committee-redesign.md — structural redesign of traditional committee governance using this model --- I. Core Principle Reasoning is not individual thinking — it is a shared, iterative search process across a team. The fundamental shift is from \"individuals solving problems and reporting back\" to \"a group attacking a visible problem together.\" Participants disagree with reasoning steps, stress-test assumptions, and reason forward collectively rather than deferring to hierarchy or individual expertise. --- II. The Team Reasoning Model 1. Problem as a Shared Object Instead of assigning tasks, externalize the problem. The problem is made visible to all participants and continuously refined as understanding deepens. Key Rule: No private reasoning for system-level decisions. All reasoning happens in the shared space. 2. Reasoning in Public Each participant follows a transparent reasoning format: Phase Description --- --- Observation What we see in t",
