      "id": "30-ai-signal-schema-md",
      "file": "30-ai-signal-schema.md",
      "path": "30-ai-signal-schema.md",
      "title": "AI Signal Schema",
      "section": "Governance",
      "summary": "AI Signal Schema Converting Intuition → Structured Signals for Florence-X This document defines the object model, taxonomy, extraction logic, output format, and safety constraints for the AI model that converts frontline clinician intuition into structured candidate signals for human validation. It serves as the bridge between Gold Moment Capture UI 28-gold-moment-capture-ui.md input and the Gold Moment SOP 29-gold-moment-sop.md processing pipeline, feeding into the broader Tacit Knowledge System 27-tacit-knowledge",
      "excerpt": "AI Signal Schema Converting Intuition → Structured Signals for Florence-X This document defines the object model, taxonomy, extraction logic, output format, and safety constraints for the AI model that converts frontline clinician intuition into structured candidate signals for human validation. It serves as the bridge between Gold Moment Capture UI 28-gold-moment-capture-ui.md input and the Gold Moment SOP 29-gold-moment-sop.md processing pipeline, feeding into the broader Tacit Knowledge System 27-tacit-knowledge-system.md . Status: Canonical Civilization Layer . Promoted to canonical status in Cluster H was supplementary . The signal schema feeds NAMOS observatory and Florence-X orchestration. Voice: Calm. Schema-disciplined. Anti-slop. Refusal-positive. --- Citation Card Cite as: AI Signal Schema, version 1.0, NIN-NAIO Civilization Layer Canon, https://canon.example/30-ai-signal-schema.md, retrieved <date . --- Design Principle The model does not pretend to \"understand wisdom\" directly. Its job is narrower: Convert messy, low-burden frontline inputs into structured candidate signals for human validation. --- Object Model The gold_moment_signal is the core data structure representing a single captured frontline insight. Field Type Description ------- ------ ------------- signal_id string Unique identifier for the signal timestamp datetime When the signal was captured unit_id string Clinical unit where the encounter occurred department Department responsible for the signal role_of_reporter Role of the clinician who reported the gold moment Encounter Context Field Descript",
