      "summary": "Fellowship Module: From Intuition to System Intelligence NIN Level 2–3 Training Module This document describes the NIN/NAIO/Florence-X fellowship module that teaches clinicians and frontline staff to recognize, capture, validate, and operationalize tacit knowledge. It covers the full pipeline from frontline intuition to structured system intelligence — including Gold Moment capture, team validation, and downstream workflow integration.",
      "excerpt": "Fellowship Module: From Intuition to System Intelligence NIN Level 2–3 Training Module This document describes the NIN/NAIO/Florence-X fellowship module that teaches clinicians and frontline staff to recognize, capture, validate, and operationalize tacit knowledge. It covers the full pipeline from frontline intuition to structured system intelligence — including Gold Moment capture, team validation, and downstream workflow integration. This module connects the Tacit Knowledge System See Tacit Knowledge System 27-tacit-knowledge-system.md , Gold Moment SOP See Gold Moment SOP 29-gold-moment-sop.md , and the broader Certification Curriculum See Certification Curriculum P1_AI_Aware_Physician_Curriculum.docx and Competency Framework See Competency Framework 35-reviewer-bench-curriculum.md . --- Module Purpose Train clinicians and frontline staff to: - Recognize tacit knowledge in real work - Surface it clearly - Distinguish intuition from evidence - Collaborate to validate patterns - Translate frontline wisdom into workflows, training, and governance Module Positioning This is a Level 2–3 NIN / NAIO / Florence-X fellowship module . It sits between basic AI familiarity and advanced orchestration / governance. It teaches the learner how to become a signal steward , not just a tool user. --- Learning Outcomes By the end of the module, participants will be able to: 1. Define tacit knowledge in frontline healthcare 2. Distinguish signal, intuition, story, and hindsight 3.",
