      "excerpt": "The Full Stack Program A Nurse Participation Architecture for the Civilization Layer File Reference: 32-full-stack-program.md Scope: A structured program that gives every participating nurse citizenship, contribution lanes, and agency across all eight layers of the civilization stack — not just the Human Interface layer. Complements the Level 1–5 vertical fellowship with a horizontal participation model. The program operates inside the three-role Human Interface nurse / physician / allied clinician ; physician participation runs in parallel through the P-1/P-2/P-3/P-4 curricula, and allied-clinician participation through discipline-specific safety pathways. Related Documents: - Florence-X + NIN Full Stack Architecture 10-florence-architecture.md v2.0 — the eight-layer architecture this program is mapped to - NIN Fellowship Experience Design 20-fellowship-design.md — the vertical progression this program complements - Reviewer Bench Curriculum 35-reviewer-bench-curriculum.md — the skill taxonomy this program draws from - P-1 AI-Aware Physician Curriculum P1_AI_Aware_Physician_Curriculum.docx — the parallel physician track under Charter §2.8 Joint Clinical Authority - Stack Passport Entry Kit 33-stack-passport-entry-kit.md — the entry-side companion to this program - NIN Provisions 43-nin-provisions.md — the citizenship-tier material support coupled to Stack Passport progression - Install Base Growth Engine 19-install-base-growth-engine.md — how stack citizens drive adoption - Cultural Playbook 18-cultural-playbook.md — the behavioral foundation this program reinforces --- I.",
