      "summary": "Adversarial and Red Team Doctrine Status: Canonical Civilization Layer . Owners: NAIO Office IV Operational Gating ; Security Lead; EDENA Safety/Ethics Lead; NAMOS Signal Lead. Companion docs: 04-naio-constitutional-charter.md §3.4, §7.2 ; Information-Security-and-Data-Governance-Policy.md ; Vendor-Risk-Management-Doctrine.md ; Florence-X-UnitOps-Security-Threat-Model.md ; Headless-Canon-Strategy.md ; Integrated-Incident-Command-Doctrine.md ; 26-ai-slop-trust-framework.md ; NAMOS-Doctrine-and-Operating-Blueprint.md",
      "excerpt": "Adversarial and Red Team Doctrine Status: Canonical Civilization Layer . Owners: NAIO Office IV Operational Gating ; Security Lead; EDENA Safety/Ethics Lead; NAMOS Signal Lead. Companion docs: 04-naio-constitutional-charter.md §3.4, §7.2 ; Information-Security-and-Data-Governance-Policy.md ; Vendor-Risk-Management-Doctrine.md ; Florence-X-UnitOps-Security-Threat-Model.md ; Headless-Canon-Strategy.md ; Integrated-Incident-Command-Doctrine.md ; 26-ai-slop-trust-framework.md ; NAMOS-Doctrine-and-Operating-Blueprint.md . Voice: Calm. Adversary-aware. Refusal-positive. Defensive. Disciplined. Anti-theatrical. --- 1. Why This Doctrine Exists The canon assumes good-faith use in most of its language. Real systems face bad-faith use: external attackers, insiders gone wrong, agents compromised, supply chain corrupted, prompts injected, social engineering of clinicians, fraudulent attestations, fake credentials, model extraction, training-data poisoning, agent jailbreaks, and the slow drift of incentive misalignment. This doctrine specifies the canon's adversarial posture: who we expect to attempt harm, what we red-team to find first, how we test ourselves, what we refuse to do in the name of testing, and how we feed findings back into the canon. The doctrine sits between the Information Security Policy which establishes baseline controls and the Integrated Incident Command Doctrine which governs response . Adversarial discipline is what makes the policy real — what we test, we know. --- 2. Doctrine The Adversarial and Red Team Doctrine operates under twelve rules. Rule Meaning --- --",
      "headings": [
        "1. Why This Doctrine Exists",
        "2. Doctrine",
        "3. Threat Model",
        "3.1 External attacker",
        "3.2 Insider — malicious",
        "3.3 Insider — compromised",
        "3.4 Insider — coerced",
        "3.5 Supply-chain attacker",
        "3.6 Adversarial agent inputs",
        "3.7 Model attacker",
        "3.8 Social engineer",
        "3.9 Reputation attacker",
        "3.10 Surveillance and harm-mission actor",
        "3.11 Drift and incentive misalignment"
      ],
