      "summary": "AI Agent Lifecycle Doctrine Status: Canonical Civilization Layer . Owners: NAIO Office IV Operational Gating ; Florence-X Engineering Lead; EDENA Safety/Ethics Lead; Programmability Registry Steward; Spec Author Registry Steward. Companion docs: 04-naio-constitutional-charter.md §2.8 Joint Clinical Authority; §3.4 Stack Transparency; §4.5 Spec Author of record ; 47-programmability-registry-spec.md ; 50-programmability-audit-methodology.md ; AI-Assistance-Scope-of-Practice-Map.md ; Information-Security-and-Data-Gove",
      "excerpt": "AI Agent Lifecycle Doctrine Status: Canonical Civilization Layer . Owners: NAIO Office IV Operational Gating ; Florence-X Engineering Lead; EDENA Safety/Ethics Lead; Programmability Registry Steward; Spec Author Registry Steward. Companion docs: 04-naio-constitutional-charter.md §2.8 Joint Clinical Authority; §3.4 Stack Transparency; §4.5 Spec Author of record ; 47-programmability-registry-spec.md ; 50-programmability-audit-methodology.md ; AI-Assistance-Scope-of-Practice-Map.md ; Information-Security-and-Data-Governance-Policy.md ; Vendor-Risk-Management-Doctrine.md ; Adversarial-and-Red-Team-Doctrine.md ; AI-Agent-Rights-and-Non-Rights-Posture.md ; 10-florence-architecture.md . Voice: Calm. Operationally explicit. Refusal-positive. Joint-authority-aware. Anti-orphan. Anti-surprise. --- 1. Why This Doctrine Exists The Agentic Civilization Layer Doctrine names agents and the AI-Assistance Scope-of-Practice Map specifies the modes and domains in which agents may operate. The Programmability Registry records workflow inspectability at registration and audit. What the canon has lacked is a doctrine specifying the lifecycle of an agent itself — how it is proposed, registered, scoped, validated, deployed, monitored, drift-detected, and retired. Without a lifecycle doctrine, agents accrete in pilot environments without governance. Spec authoring is improvised. Drift goes undetected. Retirement is \"the agent stopped being called\" rather than a decision. Multi-agent orchestration becomes opaque. Agent identity blurs into the human's identity. Agent provenance becomes a question onl",
