      "excerpt": "AI-Assistance Scope-of-Practice Map Status: Canonical Civilization Layer . Owners: NAIO Office IV Operational Gating ; Charter §2.8 Joint Clinical Authority Working Group; EDENA Safety/Ethics Lead; Cultural Adaptation Lead. Companion docs: 04-naio-constitutional-charter.md §2.8 Joint Clinical Authority; §5.5 Allied Clinician Workforce Authority; §5.6 Physician AI Credentialing ; 12-human-layer-definition.md ; physician curricula P2_ , P3_ , P4_ ; allied credentialing pathways; Patient-Facing-AI-Doctrine.md ; Vulnerable-Populations-Doctrine.md ; Country-Implementation-Profile-Template.md . Voice: Calm. Operationally explicit. Joint-authority. Refusal-positive. No scope creep. No scope dump. --- 1. Why This Map Exists The Charter is unambiguous: nurses orchestrate, physicians decide within scope, allied clinicians hold discipline-specific safety. §2.8. The physician credentialing ladder P-1 through P-4 and the allied credentialing pathways AP, AR, AL, AT, AD, AS — three tiers each operationalize who is credentialed for what. What the canon has not yet specified, in one place, is which AI assistance modes are permissible at which clinical scope across which clinical domain . That gap is operationally consequential. Nurses, physicians, and allied clinicians work side by side at a bedside; AI may be permissible at one's hands and refused at another's; the answer differs by domain diagnosis vs. coordination vs. prescribing and by patient context vulnerable population, risk zone . Without a map, every workflow argues itself. This map is the canonical answer. It does not replace cl",
