      "excerpt": "Bias and Equity Audit Methodology Status: Canonical Civilization Layer . Peer methodology to 50-programmability-audit-methodology.md . Owners: NAIO Office III Audit and Methodology ; EDENA Safety/Ethics Lead; Patient and Family Voice Council two required members per audit . Companion docs: 04-naio-constitutional-charter.md §3.4 Programmability Audit; §2.8 Joint Clinical Authority; §2.9 Patient Dignity ; 47-programmability-registry-spec.md sibling registry ; 50-programmability-audit-methodology.md peer methodology ; Patient-and-Family-Voice-Council-Charter.md ; Vulnerable-Populations-Doctrine.md ; Patient-Facing-AI-Doctrine.md . Voice: Calm. Statistically precise. Vendor-neutral. Refusal-positive. Subgroup-honest. --- 1. Why This Methodology Exists The Programmability Audit 50-programmability-audit-methodology.md establishes whether a workflow is decomposable, specifiable, and verifiable. It does not establish whether the workflow performs equitably across patient populations. The Bias and Equity Audit Methodology fills that gap. It is the canon's peer audit methodology to Programmability — same discipline, same audit cadence options, same risk-zone integration, same registry posture. It computes a Bias and Equity Ratio BER , surfaces equity harms by subgroup, and binds remediation to risk-zone-specific timelines. Where the Programmability Audit asks \"is this workflow inspectable?\", the Bias and Equity Audit asks \"does this workflow work for everyone it touches — and where it does not, are we honest about it, and are we remediating it?\" A workflow can have a perfect Programm",
