      "section": "Governance",
      "summary": "Founder Transition and Succession Doctrine Status: Canonical Civilization Layer . Owners: Stack Congress canonical authority ; each entity's board NAIO Institute, NINE² Inc and managing member NIN LLC ; General Counsel; Patient and Family Voice Council Liaison. Companion docs: 04-naio-constitutional-charter.md Stewards and Keepers; §3.4 Stack Transparency ; Legal-Entity-Architecture-Doctrine.md ; Treasury-and-Capital-Stack-Doctrine.md ; 43-nin-provisions.md ; 51-stack-congress-operating-template.md ; Patient-and-Fa",
