      "section": "Governance",
      "summary": "Media Relations Strategy Playbook Status: Canonical Civilization Layer Owners: FMN Narrative Lead, Media Relations Lead, NAIO Governance Reviewer, EDENA Safety/Ethics Reviewer Companion docs: FMN-Doctrine-and-Operating-Blueprint.md , FMN-Editorial-Governance-Manual.md , NAMOS-Doctrine-and-Operating-Blueprint.md , Headless-Canon-Strategy.md , Country-Implementation-Profile-Template.md , 04-naio-constitutional-charter.md Charter §2.8 Joint Clinical Authority Voice: Calm.",
