      "excerpt": "NAMOS — Healthcare AI & Orchestration Signal Observatory Doctrine and Operating Blueprint The signal-monitoring, market-research, and adoption-intelligence layer of the NIN–NAIO ecosystem. Detects where AI is entering nursing and healthcare operations, who is controlling it, what risks are emerging, and where nurse-led, joint-clinical-authority orchestration can create measurable value — early enough to shape strategy across the canon's other layers. File reference: NAMOS-Doctrine-and-Operating-Blueprint.md Version: 1.0 — Aligned and Improved Edition Status: Canonical intelligence layer . Sibling to NIN, NAIO, EDENA, Florence-X, NINE², and FMN. This document supersedes a prior unaligned working draft and brings the NAMOS doctrine into the broader canon's voice, discipline, joint-clinical-authority frame, cross-border awareness, and integration with the existing canonical infrastructure. Audience: NAMOS Director and team; NAIO Office VII Strategic Pilots & Rollout coordination; FMN editorial team for narrative-signal coordination; NIN Office II for workforce-signal coordination; Florence-X product team for orchestration-opportunity signal coordination; NINE² program team for cohort-theme signal coordination; institutional executive sponsors; Stack Congress delegates. Scope: Full doctrine and operating blueprint for NAMOS. Covers strategic purpose, why this is needed now, doctrine and operating principles, the signal loop, comprehensive signal taxonomy, healthcare AI adoption maturity model, orchestration readiness scoring, signal scoring model, signal registry schema, market",
