      "section": "Governance",
      "summary": "NINE² — Healthcare Innovation Incubator Application and Recruitment Kit Recruitment and application materials for launching a NINE² cohort. Companion to the Doctrine and Program Blueprint and the 12-Week Syllabus. File reference: NINE2-Application-Kit.md Version: 1.0 — Inaugural Status: Canonical recruitment kit . Companion to NINE2-Doctrine-and-Program-Blueprint.md NINE2-Doctrine-and-Program-Blueprint.md and NINE2-12-Week-Syllabus.md NINE2-12-Week-Syllabus.md .",
