      "excerpt": "NINE² — Demo Day Pitch Deck Template A 20-slide template that every NINE² team uses for the Demo Day pitch. Slide-by-slide structure, content guidance, time allocation, common mistakes, and the canonical voice rules. Companion to the Doctrine and Program Blueprint. File reference: NINE2-Demo-Day-Pitch-Deck-Template.md Version: 1.0 — Inaugural Status: Canonical presentation template . Companion to NINE2-Doctrine-and-Program-Blueprint.md NINE2-Doctrine-and-Program-Blueprint.md . Audience: Cohort participants preparing demo day pitches; mentors coaching teams; pitch coaches; faculty; future-cohort participants. Compliance note. The template encourages disclosure of AI use, patient story handling, and governance review. Specific institutional disclosure standards may require additional content; consult Privacy/Compliance Advisor. --- How to Use This Template Time Allocation Total presentation: 12 minutes plus 5 minutes of judge Q&A . Each slide has a target time. Teams that over-run on early slides starve later slides. Pitch coaches enforce the time discipline. Voice Rules The canonical voice rules apply to every slide: - Calm; clinically precise; vendor-neutral. - No hype; no hedging; no advocacy voice. - Patient at the center, not the AI. - Evidence on the page, not just claims. - Refusal as a feature; AI assists, humans remain accountable. Visual Discipline - Single thought per slide.",
