      "id": "patient-and-family-voice-council-charter-md",
      "file": "Patient-and-Family-Voice-Council-Charter.md",
      "path": "Patient-and-Family-Voice-Council-Charter.md",
      "title": "Patient and Family Voice Council Charter",
      "section": "Governance",
      "summary": "Patient and Family Voice Council Charter Status: Canonical Civilization Layer . Owners: Patient and Family Voice Council Convenor; NAIO Office I Citizen Affairs ; EDENA Safety/Ethics Lead. Companion docs: 04-naio-constitutional-charter.md Charter §2.8 Joint Clinical Authority; §2.9 Patient Dignity; §7.2 Stop-the-Line ; 05-hospital-policy.md Workforce Commitments and Patient-Facing Sections ; Vulnerable-Populations-Doctrine.md ; Patient-Facing-AI-Doctrine.md ; Bias-and-Equity-Audit-Methodology.md ; 51-stack-congress",
      "excerpt": "Patient and Family Voice Council Charter Status: Canonical Civilization Layer . Owners: Patient and Family Voice Council Convenor; NAIO Office I Citizen Affairs ; EDENA Safety/Ethics Lead. Companion docs: 04-naio-constitutional-charter.md Charter §2.8 Joint Clinical Authority; §2.9 Patient Dignity; §7.2 Stop-the-Line ; 05-hospital-policy.md Workforce Commitments and Patient-Facing Sections ; Vulnerable-Populations-Doctrine.md ; Patient-Facing-AI-Doctrine.md ; Bias-and-Equity-Audit-Methodology.md ; 51-stack-congress-operating-template.md ; 52-cross-layer-retrospective-protocol.md . Voice: Calm. Patient-led where it matters most. Vendor-neutral. Refusal-positive. No tokenism. No unpaid extraction of patient labor. --- 1. Why This Charter Exists Every doctrine in this canon assumes patients are at the center. Until the patients and families who live healthcare can shape the canon, the canon's claim to be patient-centered is partial. The Patient and Family Voice Council the \"Council\" is the constitutional institution that carries patient and family authority into NAIO governance, NIN workforce design, EDENA refusals, Florence-X orchestration, FMN narrative, NAMOS observation, and the canonical rituals Stack Congress, Cross-Layer Retrospective, Programmability Audit, Bias and Equity Audit . This charter turns \"Patient Voice Council\" from a name mentioned in other docs into an institution with: a defined composition, real authority including refusal authority , paid participation, term limits, succession, voice discipline, and a published seat at every governance table where AI-m",
