      "id": "patient-facing-ai-doctrine-md",
      "file": "Patient-Facing-AI-Doctrine.md",
      "path": "Patient-Facing-AI-Doctrine.md",
      "title": "Patient-Facing AI Doctrine",
      "section": "Governance",
      "summary": "Patient-Facing AI Doctrine Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; NAIO Office IV Operational Gating ; Patient and Family Voice Council; Florence-X Engineering Lead. Companion docs: 04-naio-constitutional-charter.md §2.8, §2.9 ; Patient-and-Family-Voice-Council-Charter.md ; Vulnerable-Populations-Doctrine.md ; Bias-and-Equity-Audit-Methodology.md ; AI-Assistance-Scope-of-Practice-Map.md ; 26-ai-slop-trust-framework.md ; Headless-Canon-Strategy.md .",
      "excerpt": "Patient-Facing AI Doctrine Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; NAIO Office IV Operational Gating ; Patient and Family Voice Council; Florence-X Engineering Lead. Companion docs: 04-naio-constitutional-charter.md §2.8, §2.9 ; Patient-and-Family-Voice-Council-Charter.md ; Vulnerable-Populations-Doctrine.md ; Bias-and-Equity-Audit-Methodology.md ; AI-Assistance-Scope-of-Practice-Map.md ; 26-ai-slop-trust-framework.md ; Headless-Canon-Strategy.md . Voice: Calm. Plain. Disclosure-positive. Refusal-positive. Cultural- and literacy-aware. No \"AI doctor\" framing. --- 1. Why This Doctrine Exists The canon's clinician-facing AI doctrine is well-developed: joint clinical authority, anti-slop, validation, escalation, refusal. The patient-facing surface is structurally different and was, until this doctrine, under-specified. Patient-facing AI — symptom checkers, portal chatbots, voice agents, post-discharge follow-up bots, scheduling agents, intake forms, mental health support apps, medication reminders, patient education content generators — operates with: - A user who is not clinically trained. - A user who may be in distress. - A user who may have low health literacy, language differences, sensory or cognitive disability, or developmental stage that demands adaptation. - No clinician-in-the-loop at the moment of interaction often . - No canonical refusal authority on the patient's side unless designed in. - A different consent, disclosure, and dignity surface than clinician-facing AI. The Patient-Facing AI Doctrine specifies how patient-facing AI ",
