      "excerpt": "NIN-NAIO-Florence-X-EDENA Civilization Layer The canonical document set for the Civilization Layer — the healthcare AI governance and workforce ecosystem positioning nurses as orchestrators, physicians as decision authorities, and allied clinicians as discipline-specific safety authorities. Repository version: 3.0 — Joint Clinical Authority Edition Status: Canonical. Drop-in replacement for prior README versions. What this README does: Maps the canonical document set, names the Series C convention as authoritative, identifies what is canonical, what is in active rewrite, what is superseded, and what is queued for the next batch. New readers begin here. --- I. Quick Orientation The Civilization Layer is built on three legal entities operating as a hybrid governance ecosystem, four canonical functional systems, eight architectural layers, and a workforce model in which nurses orchestrate, physicians decide, and allied clinicians hold discipline-specific safety authority over the AI systems used in healthcare. The three legal entities per Legal-Entity-Architecture-Doctrine.md Legal-Entity-Architecture-Doctrine.md : Entity Form Houses --- --- --- NIN, LLC For-profit limited liability company FMN Florence Media Network , NAMOS Healthcare AI & Orchestration Signal Observatory , commercial workforce community operations NAIO Institute Non-profit 501 c 3 public charity Charter operations, Florence-X orchestration architecture , EDENA ethics engine , the five canonical registries, audit operations, Patient and Family Voice Council, License Defense Pool, charitable educational missio",
