      "excerpt": "Robotics Incident Response Manual Status: Canonical Civilization Layer . Operationalizes Healthcare-Robotics-Governance-Doctrine.md §19 and binds to Integrated-Incident-Command-Doctrine.md . Owners: Robotics Safety Officer; Hospital Incident Commander per Integrated-Incident-Command-Doctrine.md ; Robotics Steward; Patient Safety Officer; Biomedical Engineering Robotics Lead; CISO; Patient and Family Voice Council Liaison. Voice: Calm. Patient-first. Joint-authority. Refusal-positive. Operationally explicit. Just-culture-anchored. --- 1. Incident Categories Per Healthcare-Robotics-Governance-Doctrine.md §19.1: 1. Collision — robot-human, robot-robot, robot-equipment collision. 2. Near collision — averted collision; learning event. 3. Unsafe navigation — pathway deviation, incorrect routing. 4. Patient contact event — unintended physical contact with patient. 5. Fall or injury — patient or staff fall or injury attributable to robotic action. 6. Wrong delivery logistics — wrong package, wrong location, wrong patient. 7. Medication handling error — pharmacy automation error. 8. Specimen handling error — lab automation error. 9. Equipment malfunction — device failure during operation. 10. Cybersecurity event — robot compromise, network event, unauthorized access. 11. Privacy event — unintended capture, unauthorized access to recordings. 12. Patient distress — patient-experienced harm during robotic interaction. 13. Staff injury — staff injury attributable to robotic operation.",
