      "excerpt": "Training Data and Derivative Data Doctrine Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; NAIO Office IV Operational Gating ; Privacy Officer; Patient and Family Voice Council Liaison; Florence-X Engineering Lead. Companion docs: 04-naio-constitutional-charter.md §2.9 Patient Dignity; §3.4 Stack Transparency ; Information-Security-and-Data-Governance-Policy.md ; Patient-Facing-AI-Doctrine.md §9 Consent and Data ; Vulnerable-Populations-Doctrine.md ; Bias-and-Equity-Audit-Methodology.md ; Vendor-Risk-Management-Doctrine.md §5.3 AI model provider diligence; §11 model selection ; EHR-Integration-Doctrine.md ; IP-and-Open-Source-Doctrine.md ; Patient-and-Family-Voice-Council-Charter.md . Voice: Calm. Patient-respectful. Counsel-aware. Refusal-positive. Consent-disciplined. PHI-rigorous. Anti-extraction. --- 1. Why This Doctrine Exists When pilot institutions run AI-mediated workflows under canonical doctrine, their systems generate enormous quantities of data: workflow logs, AI prompts, AI outputs, clinician overrides, patient interactions, embeddings, model gradients, and the raw clinical streams that feed them all. Each of those data layers can become training data — material used to improve a model, study a population, or generate commercial value. The canon's posture on this is the silent, high-stakes question that pilot institutions ask earliest and answer last. Without a canon-wide doctrine, every workflow argues consent; every vendor argues retention; every research project argues IRB; every embedding decision is improvised; and the canon's refu",
