      "title": "Vulnerable Populations Doctrine",
      "section": "Governance",
      "summary": "Vulnerable Populations Doctrine Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; Patient and Family Voice Council; NAIO Office III Audit and Methodology . Companion docs: 04-naio-constitutional-charter.md §2.9 Patient Dignity ; Patient-and-Family-Voice-Council-Charter.md ; Bias-and-Equity-Audit-Methodology.md ; Patient-Facing-AI-Doctrine.md ; AI-Assistance-Scope-of-Practice-Map.md ; Country-Implementation-Profile-Template.md ; 26-ai-slop-trust-framework.md .",
      "excerpt": "Vulnerable Populations Doctrine Status: Canonical Civilization Layer . Owners: EDENA Safety/Ethics Lead; Patient and Family Voice Council; NAIO Office III Audit and Methodology . Companion docs: 04-naio-constitutional-charter.md §2.9 Patient Dignity ; Patient-and-Family-Voice-Council-Charter.md ; Bias-and-Equity-Audit-Methodology.md ; Patient-Facing-AI-Doctrine.md ; AI-Assistance-Scope-of-Practice-Map.md ; Country-Implementation-Profile-Template.md ; 26-ai-slop-trust-framework.md . Voice: Calm. Specific. Refusal-positive. Population-honest. No euphemism for harm. No fragility framing for resilience. --- 1. Why This Doctrine Exists The canon treats \"patient dignity\" as a constitutional principle. In practice, dignity is differentially at risk across populations. AI in healthcare imports the field's existing structural asymmetries — under-representation in training data, harm patterns invisible to aggregate metrics, surveillance dynamics that fall heaviest on populations with the least power to refuse them, and design decisions that assume an idealized adult patient who can read, speak the dominant language, navigate a portal, and self-advocate. This doctrine names the populations for whom AI in healthcare carries elevated, specific risks; specifies the canonical refusal posture for each; and binds those refusals to operational checkpoints in the existing audit, registry, governance, and editorial machinery. The doctrine is not a list of populations to be protected from healthcare AI. It is a list of populations the canon refuses to harm with healthcare AI, and a set of struc",
